(function(){var EYE='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>';var EYE_OFF='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>';function addEye(inp){var cs=window.getComputedStyle(inp);var mb=cs.marginBottom||'0px';var w=document.createElement('div');w.style.cssText='position:relative;display:block;margin-bottom:'+mb;inp.style.marginBottom='0';inp.parentNode.insertBefore(w,inp);w.appendChild(inp);inp.style.paddingRight='40px';inp.style.width='100%';inp.style.boxSizing='border-box';var btn=document.createElement('button');btn.type='button';btn.setAttribute('aria-label','Mostrar/ocultar senha');btn.style.cssText='position:absolute;right:9px;top:0;bottom:0;margin:auto;height:20px;display:flex;align-items:center;background:none;border:none;cursor:pointer;color:#6b7280;padding:0;line-height:0;transition:color .15s;z-index:2';btn.innerHTML=EYE;btn.addEventListener('mouseenter',function(){this.style.color='#00e676'});btn.addEventListener('mouseleave',function(){this.style.color='#6b7280'});btn.addEventListener('click',function(e){e.preventDefault();var show=inp.type==='password';inp.type=show?'text':'password';btn.innerHTML=show?EYE_OFF:EYE;inp.focus();});w.appendChild(btn);}function init(){document.querySelectorAll('input[type="password"]').forEach(addEye);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();